/**
 * A turbina da baleia-corcunda — porte de `componentes/viz/turbina.js`.
 *
 * A nadadeira da jubarte tem calombos no bordo de ataque — os tubérculos. Por
 * décadas ninguém entendeu para que serviam, até descobrirem que eles mantêm o
 * fluxo COLADO à superfície em ângulos em que uma asa lisa já teria estolado.
 * Copiados para as pás de uma turbina eólica, dão mais potência e menos ruído.
 * Poucos e o fluxo descola; muitos e viram arrasto.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const turbina: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function pa(
    ctx: CanvasRenderingContext2D,
    angulo: number,
    comprimento: number,
    largura: number,
    tuberculos: number,
    cor: string,
  ): void {
    ctx.save();
    ctx.rotate(angulo);

    ctx.fillStyle = cor;
    ctx.beginPath();
    ctx.moveTo(-largura * 0.4, 0);
    ctx.lineTo(largura * 0.5, -comprimento * 0.1);
    ctx.lineTo(largura * 0.18, -comprimento);
    ctx.lineTo(-largura * 0.18, -comprimento);
    ctx.closePath();
    ctx.fill();

    // Os tubérculos, ao longo do bordo de ataque.
    for (let i = 0; i < tuberculos; i++) {
      const s = (i + 0.5) / tuberculos;
      const x = largura * 0.5 + (largura * 0.18 - largura * 0.5) * s;
      const y = -comprimento * 0.1 + (-comprimento + comprimento * 0.1) * s;
      ctx.beginPath();
      ctx.arc(x, y, largura * 0.09, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const controle = Math.max(0, numeroDe(valores, 'b', 0));
    const ok = info.ok === true;
    const potencia = numeroDe(info, 'pot', 0) / 100;
    const poucos = controle < numeroDe(info, 'alvoMin', 50);

    titulo(ctx, L, A, 'Calombos que seguram o vento');

    const eixoX = L * 0.44;
    const eixoY = A * 0.46;
    const comprimento = Math.min(L, A) * 0.3;
    const largura = comprimento * 0.42;
    const tuberculos = Math.round((controle / 100) * 9);

    // O vento. Com poucos tubérculos ele descola e vira redemoinho.
    ctx.lineWidth = 1.5;
    for (let i = 0; i < 7; i++) {
      const y = A * 0.18 + i * ((A * 0.66) / 6);
      ctx.strokeStyle = poucos ? cor.erro : cor.azulClaro;
      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      for (let x = 0; x <= eixoX - 10; x += 6) {
        const yy = poucos && x > eixoX * 0.5 ? y + Math.sin(x * 0.3 + t * 6 + i) * 6 : y;
        if (x === 0) ctx.moveTo(x, yy);
        else ctx.lineTo(x, yy);
      }
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // A torre.
    ctx.fillStyle = cor.fraco;
    ctx.beginPath();
    ctx.moveTo(eixoX - 5, eixoY);
    ctx.lineTo(eixoX - 9, A * 0.92);
    ctx.lineTo(eixoX + 9, A * 0.92);
    ctx.lineTo(eixoX + 5, eixoY);
    ctx.closePath();
    ctx.fill();

    // O rotor gira mais rápido quanto mais potência entrega.
    const giro = t * (0.5 + potencia * 2.5);
    ctx.save();
    ctx.translate(eixoX, eixoY);
    const tinta = ok ? cor.verde : poucos ? cor.erro : cor.azul;
    for (let k = 0; k < 3; k++) {
      pa(ctx, giro + k * ((Math.PI * 2) / 3), comprimento, largura, tuberculos, tinta);
    }
    ctx.restore();

    ctx.fillStyle = cor.contraste;
    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(eixoX, eixoY, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // O medidor de potência.
    const gx = L - 14;
    const gy = A * 0.18;
    const gh = A * 0.58;
    retangulo(ctx, gx, gy, 9, gh, 4, cor.trilho);
    const cheia = gh * limitar(potencia, 0, 1);
    retangulo(ctx, gx, gy + gh - cheia, 9, cheia, 4, ok ? cor.verde : cor.ouro);
    texto(ctx, 'kW', gx + 4, gy + gh + 12, limitar(A * 0.03, 8, 10), { cor: cor.fraco });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Fluxo colado e potência máxima ✔',
      poucos ? 'O fluxo descola: a pá perde força.' : 'Tubérculos demais: viram arrasto.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default turbina;
